# where k = smallest nonnegative integer such that the target cell is nonzero, searching over k with wrap.
# Equivalently for each cell find first nonzero along the up-left diagonal with torus wraparound:
def solve(A):
    n=A.shape[0]; vals=[]
    for i in range(2*n):
        row=[]
        for j in range(2*n):
            # walk up-left on torus until hitting a nonzero cell
            k=0
            while True:
                pi=(i-k)%n; pj=(j-k)%n
                if A[pi,pj]!=0: break
                k+=1
                if k>n: break
            row.append(int(A[pi,pj]))
        vals.append(row)
    return np.array(vals)
